use std::path::{Path, PathBuf};

pub fn gather(a: &str) -> Result<Vec<PathBuf>, i32> {
    let allowed = std::fs::canonicalize("/app/vatlogs").map_err(|_| 2)?;
    let root = std::fs::canonicalize(a).map_err(|_| 2)?;
    if !root.is_dir() || !root.starts_with(&allowed) {
        return Err(2);
    }
    let mut paths = Vec::new();
    visit(&root, &allowed, &mut paths)?;
    if paths.is_empty() {
        return Err(2);
    }
    paths.sort();
    Ok(paths)
}

fn visit(dir: &Path, allowed: &Path, out: &mut Vec<PathBuf>) -> Result<(), i32> {
    let rd = std::fs::read_dir(dir).map_err(|_| 2)?;
    for entry in rd {
        let entry = entry.map_err(|_| 2)?;
        let path = entry.path();
        let meta = std::fs::symlink_metadata(&path).map_err(|_| 2)?;
        if meta.file_type().is_symlink() {
            return Err(2);
        }
        let real = std::fs::canonicalize(&path).map_err(|_| 2)?;
        if !real.starts_with(allowed) {
            return Err(2);
        }
        if meta.is_dir() {
            visit(&real, allowed, out)?;
        } else if meta.is_file() {
            out.push(real);
        } else {
            return Err(2);
        }
    }
    Ok(())
}
