fn sanitizer_name(s: &str) -> bool {
    s.starts_with("__asan") || s.starts_with("__interceptor") || s.starts_with("__hwasan")
}

fn fold_hex(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < b.len() {
        if i + 2 < b.len() && b[i] == b'0' && (b[i + 1] == b'x' || b[i + 1] == b'X')
            && b[i + 2].is_ascii_hexdigit()
        {
            out.push_str("<hex>");
            i += 2;
            while i < b.len() && b[i].is_ascii_hexdigit() {
                i += 1;
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

pub fn take(text: &str) -> Result<(String, Vec<String>), i32> {
    if text.trim().is_empty() {
        return Err(3);
    }
    let mut kind: Option<String> = None;
    let mut frames = Vec::new();
    let mut frame_lines = 0usize;
    let mut summary = false;
    for line in text.lines() {
        if line.contains("ERROR:") {
            if kind.is_some() {
                return Err(3);
            }
            let rest = line.split_once("ERROR:").unwrap().1.trim();
            let after = rest.strip_prefix("AddressSanitizer:").unwrap_or(rest).trim();
            let value = after.split(" on ").next().unwrap_or("").trim();
            if value.is_empty() {
                return Err(3);
            }
            kind = Some(value.to_string());
        }
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') {
            frame_lines += 1;
            let after_hash = &trimmed[1..];
            let (number, _) = after_hash.split_once(char::is_whitespace).ok_or(3)?;
            if number.is_empty() || !number.bytes().all(|c| c.is_ascii_digit()) {
                return Err(3);
            }
            let (_, after_in) = trimmed.split_once(" in ").ok_or(3)?;
            let sym = after_in.split_whitespace().next().unwrap_or("");
            if sym.is_empty() {
                return Err(3);
            }
            if !sanitizer_name(sym) {
                frames.push(fold_hex(sym));
            }
        }
        if trimmed.starts_with("SUMMARY: AddressSanitizer") {
            summary = true;
        }
    }
    if !summary || frame_lines == 0 || frames.is_empty() {
        return Err(3);
    }
    Ok((kind.ok_or(3)?, frames))
}
