use crate::tally::Rec;
use std::fmt::Write;

pub fn emit(rows: &[Rec]) -> i32 {
    if rows.is_empty() {
        return 1;
    }
    if std::fs::create_dir_all("/app/inkbay").is_err() {
        return 1;
    }
    let mut inner = String::new();
    let mut desk = String::from("issue\tkind\tbody\n");
    for (i, r) in rows.iter().enumerate() {
        if i != 0 { inner.push(','); }
        let _ = write!(inner, "{{\"issue\":{},\"kind\":{},\"frames\":{},\"body\":{}}}",
            r.issue, jstr(&r.kind), jarr(&r.frames), jstr(&r.body));
        let _ = writeln!(desk, "{}\t{}\t{}", r.issue, r.kind, r.body);
    }
    let tpl = match std::fs::read_to_string("/app/tplbay/bound.tpl") {
        Ok(t) if t.contains("__ROWS__") => t,
        _ => return 1,
    };
    let bound = tpl.replace("__ROWS__", &inner);
    let btmp = "/app/inkbay/.bound.json.tmp";
    let dtmp = "/app/inkbay/.desk.tsv.tmp";
    if std::fs::write(btmp, bound).is_err() || std::fs::write(dtmp, desk).is_err() {
        cleanup();
        return 1;
    }
    if std::fs::rename(btmp, "/app/inkbay/bound.json").is_err()
        || std::fs::rename(dtmp, "/app/inkbay/desk.tsv").is_err()
    {
        cleanup();
        return 1;
    }
    if std::fs::write("/app/inkbay/GUARD", "ok").is_err() {
        return 1;
    }
    0
}

fn cleanup() {
    let _ = std::fs::remove_file("/app/inkbay/.bound.json.tmp");
    let _ = std::fs::remove_file("/app/inkbay/.desk.tsv.tmp");
}

fn jstr(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < ' ' => { let _ = write!(out, "\\u{:04x}", c as u32); },
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn jarr(v: &[String]) -> String {
